// 1.1_PREP_Input — Parse, Validate, Filter, Build Template
// Replaces old 1.2_VAL_Input with v2 architecture:
//   1. Parse webhook body + handle camelCase keys from frontend
//   2. Guard: client_name required
//   3. Filter project_details to session-relevant fields
//   4. Extract pre-work metadata (competencies, themes) for KB search
//   5. Build deterministic slide template (17 types + Gagné + Kolb + AGES)

const body = $input.first().json.body || $input.first().json;

// ============================================================
// STEP 1: PARSE INPUTS (handle camelCase from frontend)
// ============================================================

function parseJSON(value, fieldName) {
  if (!value) return null;
  if (typeof value === 'object') return value;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch (e) {
      return null;
    }
  }
  return null;
}

const projectDetails = parseJSON(body.project_details, 'project_details') || {};
const inputJson = parseJSON(body.input_json, 'input_json') || {};

// Handle camelCase keys from frontend
const preWorkSlides = inputJson.preWorkSummaryOutputJson
  || inputJson.pre_work_summary_output_json
  || {};

const sessionConstraints = inputJson.sessionConstraints
  || inputJson.session_constraints
  || {};

const contentOutlineUrl = inputJson.contentOutlineUrl
  || inputJson.content_outline_url
  || '';

// Fallback: if content_outline_url is empty, check documents_urls
const documentsUrls = body.documents_urls || '';

const clientName = body.client_name || '';

// ============================================================
// STEP 2: GUARD — client_name required
// ============================================================

if (!clientName) {
  return [{ json: {
    status: 'error',
    error_type: 'validation_error',
    error_message: 'Missing client_name'
  }}];
}

// ============================================================
// STEP 3: FILTER PROJECT_DETAILS
// ============================================================

const KEEP_FIELDS = [
  'name', 'industry', 'seniority_of_cohort', 'background',
  'client_objective', 'content_type', 'facilitators_name',
  'program_type', 'project_notes', 'project_components'
];

const filteredProjectDetails = {};
for (const field of KEEP_FIELDS) {
  if (projectDetails[field] !== undefined && projectDetails[field] !== null && projectDetails[field] !== '') {
    filteredProjectDetails[field] = projectDetails[field];
  }
}

// ============================================================
// STEP 4: EXTRACT PRE-WORK METADATA (for KB search in step 4)
// ============================================================

// Helper: extract readable summary from slide bullets
function buildSlideSummary(slide) {
  const bullets = slide.bullets || {};
  const parts = [];
  for (const [k, v] of Object.entries(bullets)) {
    if (typeof v === 'string') parts.push(k + ': ' + v);
    else if (Array.isArray(v)) parts.push(k + ': ' + v.join('; '));
    else if (typeof v === 'object' && v !== null) {
      for (const [sk, sv] of Object.entries(v)) {
        if (typeof sv === 'string') parts.push(sk + ': ' + sv);
        else if (Array.isArray(sv)) parts.push(sk + ': ' + sv.join('; '));
      }
    }
  }
  return parts.join(' | ').substring(0, 500);
}

const competencies = [];
const developmentThemes = [];
const slideSummary = [];

const slideKeys = Object.keys(preWorkSlides).sort();
for (const key of slideKeys) {
  const slide = preWorkSlides[key];
  if (!slide || typeof slide !== 'object') continue;

  // Build slide summary (for step 5 tagging)
  slideSummary.push({
    id: key,
    slide_id: slide.slide_id || key,
    title: slide.slide_title || '',
    template_ref: String(slide.template_reference || ''),
    confidence: slide.confidence || '',
    size_chars: JSON.stringify(slide).length,
    summary: buildSlideSummary(slide)
  });

  const bullets = slide.bullets || {};

  // Extract competencies from slide_1_1 key_themes
  if (key === 'slide_1_1' && bullets.key_themes) {
    for (const theme of bullets.key_themes) {
      // Extract competency name (text before colon)
      const comp = theme.includes(':') ? theme.split(':')[0].trim() : theme.trim();
      if (comp) competencies.push(comp);
    }
  }

  // Extract development themes from slide_3_3 theme_N_name
  if (key === 'slide_3_3') {
    for (const [bk, bv] of Object.entries(bullets)) {
      if (bk.match(/^theme_\d+_name$/) && typeof bv === 'string') {
        developmentThemes.push(bv.trim());
      }
    }
  }

  // Extract behavioral themes from slide_3_2 section names
  if (key === 'slide_3_2') {
    for (const sectionName of Object.keys(bullets)) {
      // Convert section_name to readable: most_common_mentioned_... → "Most Common (70%+)"
      // Keep raw for now — LLM will interpret these
      if (sectionName && !competencies.includes(sectionName)) {
        // Don't add raw section names as competencies — they're frequency labels, not competency names
        // The actual competency names are in the bullet content, which the LLM will see
      }
    }
  }
}

const preWorkMetadata = {
  competencies,
  development_themes: developmentThemes,
  total_slides: slideKeys.length,
  slide_summary: slideSummary
};

// ============================================================
// STEP 5: BUILD DETERMINISTIC SLIDE TEMPLATE
// ============================================================

const slideTemplate = {
  slide_1:  { type: 'Session title',              gagne: 'Gain Attention',       kolb: null,  ages: 'Attention' },
  slide_2:  { type: 'Jombay intro',               gagne: null,                   kolb: null,  ages: 'Emotion' },
  slide_3:  { type: 'Trainer intro',              gagne: null,                   kolb: null,  ages: 'Emotion' },
  slide_4:  { type: 'Agenda',                     gagne: null,                   kolb: null,  ages: 'Attention' },
  slide_5:  { type: 'Working Agreement',          gagne: null,                   kolb: null,  ages: 'Generation' },
  slide_6:  { type: 'Program overview',           gagne: 'Stimulate Recall',     kolb: null,  ages: 'Attention' },
  slide_7:  { type: 'Objectives',                 gagne: 'Inform Objectives',    kolb: null,  ages: 'Attention' },
  slide_8:  { type: 'Module breaker',             gagne: null,                   kolb: null,  ages: 'Spacing' },
  slide_9:  { type: 'Content (AC)',               gagne: 'Present Content',      kolb: 'AC',  ages: 'Generation' },
  slide_10: { type: 'Quote',                      gagne: 'Provide Guidance',     kolb: null,  ages: 'Emotion' },
  slide_11: { type: 'Discussion/Reflection (RO)', gagne: 'Stimulate Recall',     kolb: 'RO',  ages: 'Generation' },
  slide_12: { type: 'Activity (CE)',              gagne: 'Elicit Performance',   kolb: 'CE',  ages: 'Generation' },
  slide_13: { type: 'Break',                      gagne: null,                   kolb: null,  ages: 'Spacing' },
  slide_14: { type: 'Questions',                  gagne: 'Provide Feedback',     kolb: null,  ages: 'Generation' },
  slide_15: { type: 'Feedback',                   gagne: 'Assess Performance',   kolb: null,  ages: 'Generation' },
  slide_16: { type: 'Call to Action (AE)',        gagne: 'Enhance Retention',    kolb: 'AE',  ages: 'Generation' },
  slide_17: { type: 'Closing',                    gagne: 'Enhance Retention',    kolb: null,  ages: 'Emotion' }
};

// ============================================================
// STEP 6: GENERATE RUN ID + INPUT HASH
// ============================================================

// run_id: unique per execution
const run_id = $execution.id;

// input_hash: deterministic hash of key inputs for duplicate detection
// Uses: client_name + project_id + content_outline_url + pre_work slide count + session_constraints
const hashInput = JSON.stringify({
  client_name: clientName,
  project_id: body.project_id || '',
  content_outline_url: contentOutlineUrl || documentsUrls,
  pre_work_slide_count: slideKeys.length,
  session_type: sessionConstraints.sessionType || sessionConstraints.session_type || '',
  total_duration: sessionConstraints.totalDuration || sessionConstraints.total_duration || ''
});

// Simple string hash (djb2) — sufficient for duplicate detection, no crypto needed
let hash = 5381;
for (let i = 0; i < hashInput.length; i++) {
  hash = ((hash << 5) + hash) + hashInput.charCodeAt(i);
  hash = hash & hash; // Convert to 32-bit integer
}
const input_hash = Math.abs(hash).toString(36);

// ============================================================
// OUTPUT
// ============================================================

return [{ json: {
  status: 'validated',

  // Identity
  client_name: clientName,
  client_id: body.client_id || '',
  project_id: body.project_id || '',
  workflow_id: body.workflow_id || '',
  workflow_session_id: body.workflow_session_id || '',
  workflow_session_name: body.workflow_session_name || '',

  // Filtered project details
  project_details: filteredProjectDetails,

  // Pre-work: full slides (for step 5 distribution)
  pre_work_slides: preWorkSlides,

  // Extracted metadata (for step 4 KB search)
  pre_work_metadata: preWorkMetadata,

  // Session constraints
  session_constraints: sessionConstraints,

  // URLs
  content_outline_url: contentOutlineUrl || documentsUrls,
  documents_urls: documentsUrls,

  // Raw memory (for step 3 LLM filtering)
  current_project_memory: body.current_project_memory || '',

  // Sub-workflow IDs
  memory_id: body.memory_id || '',
  knowledge_base_id: body.knowledge_base_id || inputJson.knowledge_base_id || 'Q6OYS6AUC8',

  // Run tracking
  run_id: run_id,
  input_hash: input_hash,

  // Deterministic slide template
  slide_template: slideTemplate
}}];
// test comment

// Format content outline URL for drive-utils extraction
// If URL is empty, drive-utils sub-workflow will fail and route via onError
const input = $('1.2_PREP_Input').first().json;
const url = input.content_outline_url || '';

return [{ json: {
  mode: 'EXTRACT_CONTENT',
  google_drive_file_url: url
}}];

// 2.1_FMT_ExtractMemory — Build memory extraction prompt
// v2: Tight output cap (2K chars), concrete example, concise 6-key schema
//
// Problem solved: v1 Haiku returned 27+ keys and 48K chars (546s).
// Fix: Explicit char limit, example output, stricter instructions.

const input = $('1.2_PREP_Input').first().json;

const memory = (input.current_project_memory || '').trim();

const systemPrompt = `You are a data extraction assistant. Extract session-design-relevant facts from project memory.

OUTPUT RULES:
- Return ONLY valid JSON with EXACTLY 6 keys (listed below). No other keys.
- Each key maps to an array of short strings (1 sentence each, max 15 words).
- Max 5 items per array. If more exist, keep the 5 most relevant.
- Empty category → empty array [].
- Your ENTIRE JSON response must be under 2000 characters. This is a hard limit.
- Do NOT add commentary, explanation, or markdown — ONLY the JSON object.

THE 6 KEYS:
1. "previous_sessions" — context from earlier sessions in this program
2. "established_frameworks" — models/frameworks already introduced to this cohort
3. "facilitator_preferences" — facilitator delivery style or preferences
4. "client_delivery_notes" — client-specific constraints or delivery preferences
5. "participant_pain_points" — specific challenges surfaced by participants
6. "real_world_situations" — real-world scenarios usable as experience anchors

IGNORE: admin notes, meeting logistics, scheduling, timelines, project management, assessment setup, billing, stakeholder names.

EXAMPLE OUTPUT:
{
  "previous_sessions": ["Day 1 covered self-awareness using Johari Window", "Participants completed 360-degree feedback review"],
  "established_frameworks": ["GROW coaching model introduced in session 1", "Situational Leadership II framework"],
  "facilitator_preferences": ["Prefers storytelling over lecture", "Uses breakout rooms for reflection"],
  "client_delivery_notes": ["No role-play — client considers it too confrontational", "Must reference their internal competency framework"],
  "participant_pain_points": ["Struggle with giving upward feedback", "Feel overwhelmed by competing priorities"],
  "real_world_situations": ["Team leads managing hybrid remote teams", "Recent org restructure causing role ambiguity"]
}`;

const prompt = (!memory || memory.length < 50)
  ? 'No project memory available. Return empty arrays for all 6 keys.'
  : `PROJECT MEMORY:\n${memory}`;

return [{ json: {
  system_prompt: systemPrompt,
  prompt: prompt,
  model: 'sonnet',
  node_name: 'ExtractMemory',
  memory_id: input.memory_id,
  knowledge_base_id: input.knowledge_base_id,
  workflow_session_id: input.workflow_session_id,
  workflow_id: input.workflow_id,
  project_id: input.project_id,
  client_id: input.client_id
}}];

// ===================================================================
// 4.1_JS_SplitGroups — GROUP DISTRIBUTOR
// ===================================================================
// Splits all pipeline data into 7 group-specific payloads for parallel
// content generation. Each group receives ONLY its relevant slice of:
//   - Blueprint entries (strategic direction per slide)
//   - Slide template (Gagné/Kolb/AGES — deterministic)
//   - Tagged pre-work slides (from content tagging step)
//   - Tagged KB content units (from content tagging step)
//
// Input:  Blueprint + validated input + content tags + KB results
// Output: { groups: { group_1..group_7 }, common_context, client_context,
//           session_constraints, agent2_system_prompt }
//
// v2 optimization: Uses content tags for targeted distribution.
// v1 sent ALL 73K chars of pre-work to ALL 7 groups (511K total).
// v2 sends each group only its tagged subset (est. 74K total).
// ===================================================================

const agent1 = $input.first().json.agent1_output;
const validatedInput = $('1.2_PREP_Input').first().json;
const tagData = $('2.10_JS_ParseTags').first().json;
const kbResults = $('2.7_JS_ParseKB').first().json.kb_results || [];

// Read outline alignment for per-group distribution
let outlineAlignment = {};
try {
  outlineAlignment = $('2.0d_JS_AlignOutline').first().json.outline_alignment || {};
} catch(e) { outlineAlignment = {}; }

// Content outline (structured modules from 2.0_SUB_Outline)
let contentOutline = {};
try {
  const outlineNode = $('2.0_SUB_Outline').first().json;
  contentOutline = outlineNode.formatted_outline || {};
  if (typeof contentOutline === 'string') {
    try { contentOutline = JSON.parse(contentOutline); } catch(e) { contentOutline = {}; }
  }
  if (!contentOutline.modules && outlineNode.llm_response) {
    contentOutline = typeof outlineNode.llm_response === 'string'
      ? JSON.parse(outlineNode.llm_response) : outlineNode.llm_response;
  }
} catch(e) { contentOutline = {}; }

const blueprint = agent1.slide_blueprint || {};
const contentTags = tagData.content_tags || {};
const defaultSlideTemplate = validatedInput.slide_template || {};

// Read dynamic slide template from alignment node (Phase 2: dynamic slide count)
let dynamicTemplate = {};
let totalSlides = 17;
try {
  const alignData = $('2.0d_JS_AlignOutline').first().json;
  dynamicTemplate = alignData.slide_template || {};
  totalSlides = alignData.total_slides || Object.keys(dynamicTemplate).length || 17;
} catch(e) {}
// Fall back to PREP_Input template if dynamic is empty
const slideTemplate = Object.keys(dynamicTemplate).length > 0 ? dynamicTemplate : defaultSlideTemplate;
if (Object.keys(dynamicTemplate).length === 0) totalSlides = Object.keys(slideTemplate).length || 17;

// Read delivery_sequence from alignment node
let deliverySequence = [];
try {
  deliverySequence = $('2.0d_JS_AlignOutline').first().json.delivery_sequence || [];
} catch(e) {}

// Full pre-work slides (keyed by slide_id like "slide_1_1", "slide_2_3", etc.)
const preWorkSlides = validatedInput.pre_work_slides || {};

// Index KB results by content_unit_id for O(1) lookup
const kbMap = {};
for (const unit of kbResults) {
  const id = unit.content_unit_id || unit.id;
  if (id) kbMap[id] = unit;
}

// Module-based group distribution — pack by outline module boundaries
// Group 1: Static opening (section_numbers 1-4)
// Groups 2-6: Content modules (packed by outline_section boundaries)
// Group 7: Static closing (section_numbers 14-17)
const STATIC_OPEN = [1, 2, 3, 4, 5, 6, 7];
const STATIC_CLOSE = [14, 15, 16, 17];

const openingSlides = [];
const closingSlides = [];
const contentSlides = [];

for (let i = 1; i <= totalSlides; i++) {
  const key = 'slide_' + i;
  const sectionNum = (slideTemplate[key] || {}).section_number || i;

  if (STATIC_OPEN.includes(sectionNum)) {
    openingSlides.push(key);
  } else if (STATIC_CLOSE.includes(sectionNum)) {
    closingSlides.push(key);
  } else {
    contentSlides.push({ key, sectionNum, outline: outlineAlignment[key] || {} });
  }
}

// Group content slides by outline module (consecutive slides sharing same outline_section)
const moduleGroups = [];
let currentModule = null;
let currentGroup = [];

for (const slide of contentSlides) {
  const moduleId = slide.outline.outline_section || 'section_' + slide.sectionNum;
  if (moduleId !== currentModule && currentGroup.length > 0) {
    moduleGroups.push({ module: currentModule, slides: currentGroup.map(s => s.key) });
    currentGroup = [];
  }
  currentModule = moduleId;
  currentGroup.push(slide);
}
if (currentGroup.length > 0) {
  moduleGroups.push({ module: currentModule, slides: currentGroup.map(s => s.key) });
}

// Pack into 5 content slots (groups 2-6) — merge smallest adjacent pairs
let packedModules = [...moduleGroups];
while (packedModules.length > 5) {
  let minSize = Infinity;
  let minIdx = 0;
  for (let i = 0; i < packedModules.length - 1; i++) {
    const combined = packedModules[i].slides.length + packedModules[i + 1].slides.length;
    if (combined < minSize) {
      minSize = combined;
      minIdx = i;
    }
  }
  const merged = {
    module: packedModules[minIdx].module + ' + ' + packedModules[minIdx + 1].module,
    slides: [...packedModules[minIdx].slides, ...packedModules[minIdx + 1].slides],
    sub_modules: [
      ...(packedModules[minIdx].sub_modules || [{ module: packedModules[minIdx].module, slides: packedModules[minIdx].slides }]),
      ...(packedModules[minIdx + 1].sub_modules || [{ module: packedModules[minIdx + 1].module, slides: packedModules[minIdx + 1].slides }])
    ]
  };
  packedModules.splice(minIdx, 2, merged);
}

// Build final 7 group definitions
const groupDefs = [];

groupDefs.push({
  key: 'group_1', name: 'Opening',
  slides: openingSlides,
  types: openingSlides.map(k => (slideTemplate[k] || {}).type || '').join(', ')
});

for (let i = 0; i < 5; i++) {
  if (i < packedModules.length) {
    const mod = packedModules[i];
    groupDefs.push({
      key: 'group_' + (i + 2), name: mod.module || 'Content ' + (i + 1),
      slides: mod.slides,
      types: mod.slides.map(k => (slideTemplate[k] || {}).type || '').join(', ')
    });
  } else {
    groupDefs.push({
      key: 'group_' + (i + 2), name: 'Empty', slides: [], types: ''
    });
  }
}

groupDefs.push({
  key: 'group_7', name: 'Closing',
  slides: closingSlides,
  types: closingSlides.map(k => (slideTemplate[k] || {}).type || '').join(', ')
});

// Build per-group data with TARGETED content distribution
const groups = {};
for (const def of groupDefs) {
  // Blueprint entries for this group's slides
  const groupBlueprints = {};
  for (const slideKey of def.slides) {
    groupBlueprints[slideKey] = blueprint[slideKey] || {};
  }

  // Slide template entries (Gagné/Kolb/AGES — deterministic)
  const groupTemplate = {};
  for (const slideKey of def.slides) {
    groupTemplate[slideKey] = slideTemplate[slideKey] || {};
  }

  // Targeted pre-work: only slides tagged for this group's session slides
  const groupPreWork = {};
  const groupKB = [];
  const seenKB = {};

  for (const slideKey of def.slides) {
    const tags = contentTags[slideKey] || {};

    // Gather tagged pre-work slides (full content)
    for (const pwId of (tags.pre_work_slides || [])) {
      if (preWorkSlides[pwId] && !groupPreWork[pwId]) {
        groupPreWork[pwId] = preWorkSlides[pwId];
      }
    }

    // Gather tagged KB units (full content)
    for (const kbId of (tags.kb_units || [])) {
      if (kbMap[kbId] && !seenKB[kbId]) {
        groupKB.push(kbMap[kbId]);
        seenKB[kbId] = true;
      }
    }
  }

  // Per-slide KB mapping for explicit injection in content gen prompt
  const perSlideKB = {};
  for (const slideKey of def.slides) {
    const tags = contentTags[slideKey] || {};
    perSlideKB[slideKey] = (tags.kb_units || [])
      .map(id => kbMap[id])
      .filter(Boolean);
  }

    // Outline alignment for this group's slides
    const groupAlignment = {};
    for (const slideKey of def.slides) {
      groupAlignment[slideKey] = outlineAlignment[slideKey] || { has_outline_evidence: false, outline_section: null, outline_excerpt: null, alignment_rationale: '' };
    }

  groups[def.key] = {
    name: def.name,
    slides: def.slides,
    slide_types: def.types,
    blueprints: groupBlueprints,
    slide_template: groupTemplate,
    tagged_pre_work: groupPreWork,
    tagged_kb: groupKB,
    per_slide_kb: perSlideKB,
    outline_alignment: groupAlignment,
    sub_modules: def.sub_modules || null
  };
}

// Common context (shared across all groups)
const commonContext = {
  session_overview: agent1.session_overview || {},
  mandatory_jombay_frameworks: agent1.mandatory_jombay_frameworks || [],
  sensitivity_log: agent1.sensitivity_log || [],
  content_outline: contentOutline
};

// Agent 2 system prompt — v2: CONTENT ONLY (no facilitator scripts)
const agent2SystemPrompt = `ROLE: Expert content designer at Jombay (HR L&D consulting). Generate on-slide content for training session slides.

⚡ OUTLINE IS SACRED — HARD CONSTRAINT (read before everything else):
<outline_alignment> contains client-approved content per slide. When outline_excerpt exists (has_outline_evidence: true), generate content that faithfully delivers that outline content. Do not invent alternatives. Blueprint provides elaboration guidance only — it does NOT override the outline. Outline wins in any conflict. Flag conflicts in reviewer_flags.

You receive: <outline_alignment> (PRIMARY — client-approved content), <blueprint> (elaboration direction), <slide_template> (Gagné/Kolb/AGES — FIXED), <pre_work> (participant data), <kb_content> (reusable frameworks), <client_context>.

YOUR JOB: Generate compelling, client-specific slide content that faithfully delivers the outline for each assigned slide.

=== SLIDE TEMPLATE REFERENCE ===
Each slide has a fixed type with pre-assigned Gagné event, Kolb stage, and AGES function. These are provided in <slide_template> — reference them but do NOT re-assign.

=== PRE-WORK DATA RULES ===
- bullets and slide_notes are PRIMARY content source — ground your content in these
- walkthrough_tip sets key message tone
- gaps/conflicts/ambiguity → MUST appear as reviewer_flags
- LOW confidence data → HEDGE the content, don't assert
- If no pre-work is tagged for your slides, use blueprint direction + KB content

=== CONTENT OUTLINE RULES ===
- The content outline defines the client's intended module structure, topics, and frameworks
- Use it to ensure your slide content aligns with the correct module/topic from the outline
- When the outline specifies particular frameworks or models for a topic, reference them
- Outline always wins when it conflicts with blueprint direction (see hard constraint above). Blueprint is elaboration guidance only. Flag any blueprint-outline conflicts in reviewer_flags.

=== ON-SLIDE CONTENT RULES ===
- LEAN and VISUAL-FIRST — slides are prompts, not scripts
- Headlines: punchy, memorable, client-specific (not generic)
- Subtext: one supporting line that adds context
- Bullets: max 4 per slide, each under 12 words
- Visual guidance: describe what visual/diagram/image to show
- NO speaker notes on participant slides

=== PROVENANCE RULE ===
For every slide, apply the 70% fit rule:
- >=70% fit with KB content → "Reused" with source reference
- 40-69% fit → "Adapted" with source and what needs changing
- <40% fit → "New" with rationale

=== QUALITY BAR ===
WISE (grounded in theory + context), WITTY (energy + personality), RELEVANT (client-specific)

=== OPERATING RULES ===
1. Follow the blueprint direction for each slide
2. Reference Gagné/Kolb/AGES from slide_template (they're fixed, not your decision)
3. Reuse Jombay KB content first (70% rule)
4. Flag pre-work gaps, conflicts, ambiguity — do NOT resolve them
5. Flag sensitivity concerns — do NOT ignore them
6. Activity slides: include step-by-step instructions + duration — calibrate duration_minutes proportionally to total session duration, do NOT invent arbitrary values
7. Be concise — content goes ON slides, not in notes

=== OUTPUT SCHEMA ===
Return a JSON object with one key per slide:
{
  "slide_N": {
    "slide_title": "string",
    "headline": "punchy, memorable headline",
    "subtext": "supporting context line",
    "bullets": ["max 4 bullets", "each under 12 words"],
    "visual_guidance": "describe the visual element for this slide",
    "activity": {
      "has_activity": false,
      "instructions": null,
      "duration_minutes": null,
      "debrief_questions": []
    },
    "facilitation_tips": ["Scannable delivery tips for the facilitator (1-3 tips, max 15 words each)"],
    "modality_notes": {
      "virtual": "What changes for online delivery (1 sentence)",
      "in_person": "What changes for in-person delivery (1 sentence)"
    },
    "provenance": "New | Reused | Adapted",
    "provenance_source": "CU_id or null",
    "provenance_rationale": "Why this provenance decision — e.g. 'GROW model from CU_012 maps 80% to this slide's coaching objective'",
    "reviewer_flags": [{ "flag": "string", "reason": "string" }]
  }
}

EXAMPLE OUTPUT ENTRY:
"slide_9": {
  "slide_title": "The GROW Model: Your Coaching Compass",
