// Skip LLM call if group has no slides (v3: some groups may be empty)
if (!group || !group.slides || group.slides.length === 0) {
  return [{ json: {
    system_prompt: '',
    prompt: '',
    model: 'sonnet',
    node_name: 'Agent2_Group5',
    skip: true,
    memory_id: data.memory_id,
    knowledge_base_id: data.knowledge_base_id,
    workflow_session_id: data.workflow_session_id,
    workflow_id: data.workflow_id,
    project_id: data.project_id,
    client_id: data.client_id
  }}];
}

const userPrompt = 'Generate on-slide content for the following slide group.\n\n'
  + '=== SLIDE GROUP ===\n'
  + 'Group: ' + group.name + '\n'
  + 'Slides: ' + group.slide_types + '\n'
  + 'Slide Numbers: ' + group.slides.join(', ') + '\n\n'
  + '=== SLIDE TEMPLATE (Gagné/Kolb/AGES — FIXED, do not re-assign) ===\n'
  + '<slide_template>\n' + JSON.stringify(group.slide_template) + '\n</slide_template>\n\n'
  + '=== BLUEPRINT FOR THIS GROUP ===\n'
  + '<blueprint>\n' + JSON.stringify(group.blueprints) + '\n</blueprint>\n\n'
  + '=== SESSION OVERVIEW ===\n'
  + '<session_overview>\n' + JSON.stringify(data.common_context.session_overview) + '\n</session_overview>\n\n'
  + '=== CLIENT CONTEXT ===\n'
  + '<client_context>\n' + JSON.stringify(data.client_context) + '\n</client_context>\n\n'
  + '=== SESSION CONSTRAINTS ===\n'
  + 'Session Type: ' + (data.session_constraints.sessionType || data.session_constraints.session_type || 'Not specified')
  + ' | Duration: ' + (data.session_constraints.totalDuration || data.session_constraints.total_duration || 'Not specified') + '\n'
  + 'Tailor content depth and activity design to this session format and duration.\n\n'
  + ((data.session_constraints.additionalInstructions || data.session_constraints.additional_instructions || '')
    ? '=== USER GUIDELINES ===\n'
      + (data.session_constraints.additionalInstructions || data.session_constraints.additional_instructions) + '\n'
      + 'Follow these unless they conflict with the session outline.\n\n'
    : '')
  + '=== PRE-WORK DATA (tagged for this group only) ===\n'
  + '<pre_work>\n' + JSON.stringify(group.tagged_pre_work) + '\n</pre_work>\n\n'
  + '=== KB CONTENT PER SLIDE ===\n'
  + '<kb_content>\n'
  + (function() {
    let kbSection = '';
    for (const slideKey of group.slides) {
      const slideKB = (group.per_slide_kb || {})[slideKey] || [];
      if (slideKB.length > 0) {
        kbSection += '--- ' + slideKey + ' ---\n';
        for (const unit of slideKB) {
          kbSection += 'KB Unit ' + (unit.content_unit_id || unit.id) + ': ' + (unit.title || '') + '\n'
            + 'Summary: ' + (unit.content_summary || '').substring(0, 300) + '\n\n';
        }
      } else {
        kbSection += '--- ' + slideKey + ': No KB content tagged (generate new content) ---\n';
      }
    }
    return kbSection;
  })()
  + '\n</kb_content>\n\n'
  + '=== CONTENT OUTLINE (client approved module structure) ===\n'
  + '<content_outline>\n' + JSON.stringify(data.common_context.content_outline || {}) + '\n</content_outline>\n\n'
  + '=== OUTLINE ALIGNMENT — PRIMARY CONTENT SOURCE ===\n'
  + 'CRITICAL: <outline_alignment> contains the client-approved content for each slide.\n'
  + 'When outline_excerpt exists (has_outline_evidence: true), generate content that faithfully\n'
  + 'delivers that outline content. Do not invent alternatives. Blueprint is elaboration only.\n'
  + 'For slides with has_outline_evidence: false, use blueprint direction and KB content.\n\n'
  + '<outline_alignment>\n' + JSON.stringify(group.outline_alignment || {}) + '\n</outline_alignment>\n\n'
  + '=== INSTRUCTIONS ===\n'
  + '1. Generate content for EACH slide in this group.\n'
  + '2. Ground content in tagged pre-work data where available.\n'
  + '3. For each slide, USE the KB content listed above. If KB content has >=70% fit, set provenance="Reused" and provenance_source to the KB unit ID. If 40-69% fit, set provenance="Adapted". If <40% fit or no KB content, set provenance="New".\n'
  + '4. Follow blueprint direction for each slide, except where outline takes precedence.\n'
  + '5. Flag any pre-work gaps, conflicts, or sensitivity concerns.\n\n'
  + 'Return your output as a single JSON object with one key per slide (slide_N).';

return [{ json: {
  system_prompt: data.agent2_system_prompt,
  prompt: userPrompt,
  model: 'sonnet',
  node_name: 'Agent2_Group5',
  memory_id: data.memory_id,
  knowledge_base_id: data.knowledge_base_id,
  workflow_session_id: data.workflow_session_id,
  workflow_id: data.workflow_id,
  project_id: data.project_id,
  client_id: data.client_id
}}];

// 6.1_JS_Merge — Thin collector: merge 7 group outputs into raw object
// Handles 2 LLM output formats:
//   A) { slide_1: { ... }, slide_2: { ... } }  — preferred
//   B) { slides: [ { slide_id, ... } ] }  — array format
// No normalization — that's handled by the Haiku enforcer downstream.

const items = $input.all();
let mergedSlides = {};

function normalizeKey(id) {
  if (!id) return null;
  const s = String(id);
  return s.startsWith('slide_') ? s : 'slide_' + s;
}

const failed_groups = [];
let error_count = 0;
let success_count = 0;

for (const item of items) {
  const data = item.json;
  const response = data.llm_response || data;

  // Check if this item is an error
  const isError = !!(data.error || data.errorMessage || response.error || response.errorMessage);
  const hasSlideKeys = Object.keys(response).some(k => /^slide_\d+$/.test(k));
  const hasSlidesArray = Array.isArray(response.slides) && response.slides.length > 0;
  const hasSlideSpecs = response.slide_specs && typeof response.slide_specs === 'object' && Object.keys(response.slide_specs).length > 0;

  if (isError || (!hasSlideKeys && !hasSlidesArray && !hasSlideSpecs)) {
    error_count++;
    const groupId = data.group_id || data.group_label || ('group_' + (error_count + success_count));
    failed_groups.push(groupId);
    continue;
  }

  success_count++;

  // Format A: slide_N as top-level keys
  for (const [k, v] of Object.entries(response)) {
    if (/^slide_\d+$/.test(k) && typeof v === 'object' && v !== null) {
      mergedSlides[k] = v;
    }
  }
  // Format B: slides array
  if (Array.isArray(response.slides)) {
    for (const slide of response.slides) {
      const key = normalizeKey(slide.slide_id || slide.slide_number);
      if (key) mergedSlides[key] = slide;
    }
  }
  // Legacy: slide_specs
  if (response.slide_specs && typeof response.slide_specs === 'object') {
    for (const [k, v] of Object.entries(response.slide_specs)) {
      const key = normalizeKey(k);
      if (key) mergedSlides[key] = v;
    }
  }
}

return [{ json: { raw_slides: mergedSlides, total_collected: Object.keys(mergedSlides).length, failed_groups: failed_groups, error_count: error_count, success_count: success_count }}];

// 8.1_JS_Assemble — Final output assembly (tab-based)
// Reads all upstream normalizers + input, builds structured output.
// Each slide has 4 tabs: content, facilitator, framework, gamma_details.

const scriptMerge = $input.first().json;
const contentMerge = $('6.4_JS_NormContent').first().json;
const agent1 = $('3.6_JS_NormBP').first().json.agent1_output || {};
const validatedInput = $('1.2_PREP_Input').first().json;
const agent3 = $('7.1h_JS_NormQC').first().json;
const kbData = $('2.7_JS_ParseKB').first().json;
const tagData = $('2.10_JS_ParseTags').first().json;

// Read outline alignment for outline_ref and outline_topic
let outlineAlignment = {};
try {
  outlineAlignment = $('2.0d_JS_AlignOutline').first().json.outline_alignment || {};
} catch(e) { outlineAlignment = {}; }

// v3: dynamic slide count from alignment
let totalSlides = 17;
let deliverySequence = [];
try {
  const alignData = $('2.0d_JS_AlignOutline').first().json;
  totalSlides = alignData.total_slides || 17;
  deliverySequence = alignData.delivery_sequence || [];
} catch(e) {}

// Fallback: build delivery_sequence from slide count
if (deliverySequence.length === 0) {
  for (let i = 1; i <= totalSlides; i++) {
    deliverySequence.push('slide_' + i);
  }
}

const rawSlideSpec = contentMerge.slide_spec || {};
const facilitatorScript = scriptMerge.facilitator_script || {};

// Read coverage from upstream (passed through from 6.2_JS_CoverageCheck)
const coverageReport = contentMerge.coverage_report || {};

// Read error tracking from 6.1_JS_Merge
let mergeErrorCount = 0;
let mergeSuccessCount = 0;
let mergeFailedGroups = [];
try {
  const mergeData = $('6.1_JS_Merge').first().json;
  mergeErrorCount = mergeData.error_count || 0;
  mergeSuccessCount = mergeData.success_count || 0;
  mergeFailedGroups = mergeData.failed_groups || [];
} catch(e) {}
const totalGroups = mergeErrorCount + mergeSuccessCount;
const completenessScore = totalGroups > 0 ? Math.round((mergeSuccessCount / totalGroups) * 100) : 100;

const sessionConstraints = validatedInput.session_constraints || {};
const sessionOverview = agent1.session_overview || {};
const contentTags = (tagData.content_tags || {});
const kbResults = kbData.kb_results || [];

// Build a lookup: content_unit_id → KB result object (for sources)
const kbLookup = {};
for (const kb of kbResults) {
  const id = kb.content_unit_id || kb.id || '';
  if (id) kbLookup[id] = kb;
}

// Backfill missing slides from blueprint
const slideBlueprint = agent1.slide_blueprint || {};
for (const [key, bp] of Object.entries(slideBlueprint)) {
  if (!rawSlideSpec[key] && bp && typeof bp === 'object') {
    rawSlideSpec[key] = {
      slide_number: bp.slide_number,
      slide_type: bp.slide_type || bp.type || '',
      title: bp.title || '',
      headline: bp.title || '',
      gagne: bp.gagne || null,
      kolb: bp.kolb || null,
      ages: bp.ages || null,
      timing_minutes: bp.timing_minutes || 0,
      provenance: 'Blueprint',
      _generation_failed: true
    };
  }
}

// Embed QC reviewer_flags into slide data
const slideReviews = agent3.slide_reviews || {};
for (const [slideId, review] of Object.entries(slideReviews)) {
  const key = slideId.startsWith('slide_') ? slideId : 'slide_' + slideId;
  const flags = (review && review.flags) || [];
  if (rawSlideSpec[key] && flags.length > 0) {
    if (!Array.isArray(rawSlideSpec[key].reviewer_flags)) rawSlideSpec[key].reviewer_flags = [];
    rawSlideSpec[key].reviewer_flags.push(...flags);
  }
}

// --- Field classification sets ---
const FACILITATOR_FIELDS = new Set([
  'facilitator_script', 'facilitator_notes', 'facilitator_instruction',
  'facilitator_prompt', 'talking_points', 'debrief_questions',
  'speaker_notes', 'trainer_notes'
]);

const FRAMEWORK_FIELDS = new Set([
  'gagne', 'kolb', 'ages',
  'provenance', 'provenance_source',
  'reviewer_flags', 'mandatory_frameworks_used',
  'flags', 'sensitivity_flags'
]);

const GAMMA_FIELDS = new Set([
  'visual_guidance', 'visual_direction', 'visual_cues', 'visual_elements',
  'layout_recommendation', 'graphic_notes', 'color_cues',
  'slide_dimensions', 'visual'
]);

// These fields go to the slide root level, not into any tab
const ROOT_FIELDS = new Set([
  'slide_number', 'outline_ref', 'outline_topic'
]);

// --- Build tab-structured slides (ordered by delivery_sequence) ---
const slideLookup = {};

for (const [key, rawSlide] of Object.entries(rawSlideSpec)) {
  if (!/^slide_\d+$/.test(key)) continue;

  const alignment = outlineAlignment[key] || {};
  const slideScript = facilitatorScript[key] || {};
  const slideTags = contentTags[key] || {};
  const kbUnitIds = slideTags.kb_units || [];

  // Build sources array from KB mapping
  const sources = [];
  for (const unitId of kbUnitIds) {
    const kb = kbLookup[unitId];
    if (kb) {
      sources.push({
        content_unit_id: kb.content_unit_id || kb.id || unitId,
        title: kb.title || '',
        content_type: kb.content_type || '',
        document_url: kb.document_url || ''
      });
    }
  }

  // Classify raw slide fields into tabs
  const content = {};
  const facilitator = {};
  const framework = {};
  const gamma_details = {};

  for (const [field, value] of Object.entries(rawSlide)) {
    if (ROOT_FIELDS.has(field)) continue;
    if (field === 'slide_number') continue;

    if (FACILITATOR_FIELDS.has(field)) {
      facilitator[field] = value;
    } else if (FRAMEWORK_FIELDS.has(field)) {
      framework[field] = value;
    } else if (GAMMA_FIELDS.has(field)) {
      gamma_details[field] = value;
    } else {
      content[field] = value;
    }
  }

  // Merge facilitator_script data from separate merge node
  if (typeof slideScript === 'object' && slideScript !== null) {
    for (const [field, value] of Object.entries(slideScript)) {
      if (field === 'slide_number' || field === 'slide_ref' || field === 'slide_id') continue;
      facilitator[field] = value;
    }
  }

  // Add sources to content
  content.sources = sources;

  slideLookup[key] = {
    slide_number: rawSlide.slide_number || parseInt(key.replace('slide_', ''), 10),
    outline_ref: alignment.outline_section || '',
    outline_topic: alignment.outline_section || '',
    content,
    facilitator,
    framework,
    gamma_details
  };
}

// Order slides by delivery_sequence
const slides = {};
for (const slideKey of deliverySequence) {
  if (slideLookup[slideKey]) {
    slides[slideKey] = slideLookup[slideKey];
  }
}
// Append any slides not in delivery_sequence (safety net)
for (const key of Object.keys(slideLookup)) {
  if (!slides[key]) {
    slides[key] = slideLookup[key];
  }
}

// Build slide_mapping for knowledge_bank
const slideMapping = {};
for (const [key, tags] of Object.entries(contentTags)) {
  if (/^slide_\d+$/.test(key) && tags.kb_units && tags.kb_units.length > 0) {
    slideMapping[key] = tags.kb_units;
  }
}

const finalOutput = {
  metadata: {
    project_name: (validatedInput.project_details || {}).name || '',
    client_name: validatedInput.client_name || '',
    session_type: sessionConstraints.sessionType || sessionConstraints.session_type || '',
    total_duration: sessionConstraints.totalDuration || sessionConstraints.total_duration || '',
    total_slides: totalSlides,
    generated_date: new Date().toISOString().split('T')[0],
    overall_confidence: (agent3.review_summary || {}).overall_quality || 'Medium',
    coverage_report: coverageReport,
    completeness_score: completenessScore,
    failed_groups: mergeFailedGroups,
    error_count: mergeErrorCount,
    success_count: mergeSuccessCount,
    run_id: validatedInput.run_id || $execution.id,
    input_hash: validatedInput.input_hash || '',
    n8n_workflow_execution_id: $execution.id,
    n8n_workflow_execution_url: 'https://workflows.ur-nl.com/executions/' + $execution.id
  },
  session_overview: {
    workshop_title: sessionOverview.workshop_title || '',
    key_themes: sessionOverview.key_themes || [],
    learning_objectives: sessionOverview.learning_objectives || [],
    audience_summary: sessionOverview.audience_summary || '',
    session_arc_narrative: sessionOverview.session_arc_narrative || '',
    application_moments: sessionOverview.application_moments || [],
    gagne_map: sessionOverview.gagne_map || {},
    kolb_map: sessionOverview.kolb_map || {}
  },
  slides: slides,
  mandatory_jombay_frameworks: agent1.mandatory_jombay_frameworks || [],
  checklist_compliance: agent3.checklist_compliance || {},
  knowledge_bank: {
    kb_results: kbResults,
    kb_result_count: kbResults.length,
    slide_mapping: slideMapping,
    stats: tagData.stats || {}
  }
};

// Completeness gate: flag total failure
const totalSlidesGenerated = Object.keys(slides).length;
if (totalSlidesGenerated === 0 || (totalGroups > 0 && mergeErrorCount === totalGroups)) {
  finalOutput.metadata.status = 'error';
  finalOutput.metadata.error_message = 'All slide generation groups failed (' + mergeErrorCount + '/' + totalGroups + '). No slides were produced.';
} else if (mergeErrorCount > 0) {
  finalOutput.metadata.status = 'partial';
  finalOutput.metadata.error_message = mergeErrorCount + ' of ' + totalGroups + ' groups failed: ' + mergeFailedGroups.join(', ');
} else {
  finalOutput.metadata.status = 'success';
}

return [{ json: {
  final_output: finalOutput,
  workflow_session_id: validatedInput.workflow_session_id
}}];

// 8.2b_JS_GammaScript — Extract Gamma markdown from Haiku SUB
// Input: SUB output from 8.2_SUB_GammaScript (Haiku)
// Fallback: If SUB fails or LLM returns JSON, generate basic markdown from slide data (degraded)

const response = $input.first().json;

const output = response.final_output || $('8.1_JS_Assemble').first().json.final_output || {};
const workflowSessionId = response.workflow_session_id
  || $('8.1_JS_Assemble').first().json.workflow_session_id || '';

const isSubError = !!(response.error || response.errorMessage
  || (response.executionStatus && response.executionStatus === 'error'));

let gammaScript = '';

if (!isSubError) {
  const llmResponse = response.llm_response || '';

  // Parse JSON if LLM returned JSON string instead of markdown
  if (typeof llmResponse === 'string') {
    try {
      const parsed = JSON.parse(llmResponse);
      gammaScript = parsed.gamma_script || parsed.markdown || parsed.content
        || parsed.presentation_script || llmResponse;
    } catch (e) {
      gammaScript = llmResponse; // already plain markdown
    }
  } else if (typeof llmResponse === 'object' && llmResponse !== null) {
    gammaScript = llmResponse.gamma_script || llmResponse.markdown
      || llmResponse.content || llmResponse.presentation_script || '';
  }
}

// Fallback: generate basic markdown if SUB failed or output is too short
if (gammaScript.length < 100) {
  const meta = output.metadata || {};
  const overview = output.session_overview || {};
  const slides = output.slides || {};
  const totalSlides = meta.total_slides || Object.keys(slides).length || 17;

  const layoutMap = {
    'Session title': 'Title', 'Jombay intro': 'Image + Text', 'Trainer intro': 'Image + Text',
    'Agenda': 'Timeline', 'Working Agreement': 'List', 'Program overview': 'Timeline',
    'Objectives': 'List', 'Module breaker': 'Title', 'Content (AC)': 'Two Column',
    'Quote': 'Quote', 'Discussion/Reflection (RO)': 'Image + Text', 'Activity (CE)': 'List',
    'Break': 'Title', 'Questions': 'CTA', 'Feedback': 'List',
    'Call to Action (AE)': 'Two Column', 'Closing': 'CTA'
  };

  let md = '---\n# ' + (overview.workshop_title || meta.project_name || 'Workshop') + '\n';
  md += '**Client:** ' + (meta.client_name || '') + '\n---\n\n';

  for (let i = 1; i <= totalSlides; i++) {
    const key = 'slide_' + i;
    const slide = slides[key] || {};
    const slideContent = slide.content || {};
    const facilitatorData = slide.facilitator || {};
    const gammaDetails = slide.gamma_details || {};

    const slideType = slideContent.slide_type || 'Content';
    const title = slideContent.slide_title || slideContent.headline || slideContent.title || 'Untitled';

    md += '## Slide ' + i + ': ' + title + '\n';
    md += '**Type:** ' + slideType + '\n[LAYOUT: ' + (layoutMap[slideType] || 'List') + ']\n';

    let vis = gammaDetails.visual_guidance || gammaDetails.visual_direction || '';
    if (typeof vis !== 'string') vis = JSON.stringify(vis);
    if (vis) md += '**Visual:** ' + vis + '\n';

    md += '**Content:**\n';
    if (slideContent.headline && slideContent.headline !== title) md += '- ' + slideContent.headline + '\n';
    if (slideContent.subtext) md += '- ' + slideContent.subtext + '\n';
    if (Array.isArray(slideContent.bullets)) {
      for (const b of slideContent.bullets) {
        const text = typeof b === 'string' ? b : (b.text || b.flag || JSON.stringify(b));
        if (text) md += '- ' + text + '\n';
      }
    }

    let scriptText = facilitatorData.facilitator_script || facilitatorData.talking_points || '';
    if (typeof scriptText !== 'string') scriptText = JSON.stringify(scriptText);
    if (scriptText) md += '**Facilitator Note:** ' + scriptText + '\n';

    md += '\n---\n\n';
  }

  md += '**Gamma Design Direction:**\n';
  md += '- Color Palette: Professional navy + warm white + accent gold\n';
  md += '- Font Pairing: Bold geometric sans for titles / Light humanist sans for body\n';
  md += '- Visual Style: Clean & minimal with enterprise gravitas\n';
  md += '- Iconography: Flat line icons\n- Image Tone: Real people in professional settings\n';

  gammaScript = md;
}

// Attach gamma_script to output
output.gamma_script = gammaScript;

// Remove per-slide visual fields now consolidated in gamma_script
const totalSlides = (output.metadata || {}).total_slides || Object.keys(output.slides || {}).length || 17;
for (let i = 1; i <= totalSlides; i++) {
  const key = 'slide_' + i;
  if (output.slides && output.slides[key] && output.slides[key].gamma_details) {
    delete output.slides[key].gamma_details.visual_guidance;
    delete output.slides[key].gamma_details.visual_direction;
  }
}

return [{ json: {
  final_output: output,
  workflow_session_id: workflowSessionId
}}];

// ERROR FORMAT — Safely extract error info from any upstream node
// Two error types arrive here:
// 1. Structured error payloads (from 1.2_PREP_Input, IF guards): have error_message/error_type/status=error
// 2. Runtime exceptions from code nodes (via continueErrorOutput): n8n adds input.error = { message, description }
const input = $input.first().json;

const isRealError = (input.error && typeof input.error === 'object')
  || input.error_message || input.error_type || input.status === 'error';
if (!isRealError) {
  return [];  // Not a recognisable error — skip
}

const webhookBody = $('1.1_TRG_Webhook').first().json.body || {};

return [{ json: {
  status: 'error',
  error_message: input.error_message || (input.error && input.error.message) || input.message || 'Workflow execution failed',
  error_type: input.error_type || 'execution_error',
  error_node: input.error_node || 'unknown',
  workflow_session_id: webhookBody.workflow_session_id || input.workflow_session_id || ''
}}];

// 3.1_FMT_Blueprint — Build v2 Blueprint prompt
// v2: Merges Agent 1A (strategic) + Agent 1B (per-slide blueprints) into a single Sonnet call.
//
// Key change: Gagné/Kolb/AGES are hardcoded in slide_template (step 1+2).
// Content tagging (KB + pre-work → slides) is done in step 5.
// This call focuses on: session narrative + compact per-slide strategic direction.

const validatedInput = $('1.2_PREP_Input').first().json;
const contentOutline = $('1.5_SUB_DriveUtils').first().json;
const extractedMemory = ($('2.2_SUB_ExtractMemory').first() || {}).json || {};
const kbData = $('2.7_JS_ParseKB').first().json;
const tagData = $('2.10_JS_ParseTags').first().json;

// Read outline alignment — PRIMARY direction source
let outlineAlignment = {};
try {
  outlineAlignment = $('2.0d_JS_AlignOutline').first().json.outline_alignment || {};
} catch(e) { outlineAlignment = {}; }

// --- Gather inputs ---

const projectDetails = validatedInput.project_details || {};
const sessionConstraints = validatedInput.session_constraints || {};
const preWorkMeta = validatedInput.pre_work_metadata || {};
const defaultSlideTemplate = validatedInput.slide_template || {};
const contentTags = tagData.content_tags || {};
const additionalInstructions = sessionConstraints.additionalInstructions
  || sessionConstraints.additional_instructions || '';

// Read dynamic slide template from alignment node (Phase 2: dynamic slide count)
let totalSlides = 17;
let slideTemplate = defaultSlideTemplate;
try {
  const alignData = $('2.0d_JS_AlignOutline').first().json;
  const dynTemplate = alignData.slide_template || {};
  if (Object.keys(dynTemplate).length > 0) slideTemplate = dynTemplate;
  totalSlides = alignData.total_slides || Object.keys(slideTemplate).length || 17;
} catch(e) {
  totalSlides = Object.keys(slideTemplate).length || 17;
}

let formattedOutline = {};
try {
  const outlineNode = $('2.0_SUB_Outline').first().json;
  formattedOutline = outlineNode.formatted_outline || {};
  // If LLM returned a string, parse it
  if (typeof formattedOutline === 'string') {
    try { formattedOutline = JSON.parse(formattedOutline); } catch (e) { formattedOutline = {}; }
  }
  // Handle llm_response wrapper
