    facilitator_script: facilitatorData.facilitator_script || facilitatorData.talking_points || ''
  });
}

// Build human-readable slide text — NOT JSON.stringify
// (stringify confuses LLM into returning JSON instead of markdown)
const slideDataText = slideData.map(s => {
  const bullets = Array.isArray(s.bullets)
    ? s.bullets
        .map(b => typeof b === 'string' ? b : (b.text || b.flag || JSON.stringify(b)))
        .filter(Boolean)
    : [];

  const lines = [
    'Slide ' + s.slide_number + ': ' + s.title,
    'Type: ' + s.slide_type + ' | Layout: ' + s.layout +
      ' | Provenance: ' + s.provenance +
      (s.provenance_source ? ' (' + s.provenance_source + ')' : '')
  ];
  if (s.headline && s.headline !== s.title) lines.push('Headline: ' + s.headline);
  if (s.subtext) lines.push('Subtext: ' + s.subtext);
  if (bullets.length) lines.push('Bullets:\n  - ' + bullets.join('\n  - '));
  if (s.visual_guidance) lines.push('Visual: ' + s.visual_guidance);
  if (s.activity && Object.keys(s.activity).length) {
    lines.push('Activity: ' + (typeof s.activity === 'string' ? s.activity : JSON.stringify(s.activity)));
  }
  if (Array.isArray(s.facilitation_tips) && s.facilitation_tips.length) {
    lines.push('Tips: ' + s.facilitation_tips.join('; '));
  }
  const mn = s.modality_notes;
  if (mn && (mn.virtual || mn.in_person)) {
    lines.push('Modality — Virtual: ' + (mn.virtual || '') + ' | In-person: ' + (mn.in_person || ''));
  }
  if (s.facilitator_script) lines.push('Facilitator Script: ' + s.facilitator_script);
  return lines.join('\n');
}).join('\n\n---\n\n');

