// 2.5c_FMT_KBSearch3 — Format KB search prompt (slides 11-17)
// v2: Explicitly requests Drive URLs from AgentCore.
// Finds 5 content units relevant to slides 11-17 using outline alignment.

const validatedInput = $('1.2_PREP_Input').first().json;
const projectDetails = validatedInput.project_details || {};
const sessionConstraints = validatedInput.session_constraints || {};

let outlineAlignment = {};
let totalSlides = 17;
try {
  const alignData = $('2.0d_JS_AlignOutline').first().json;
  outlineAlignment = alignData.outline_alignment || {};
  totalSlides = alignData.total_slides || 17;
} catch(e) { outlineAlignment = {}; }

// KB search 3: last third of slides
const searchStart3 = Math.ceil(totalSlides * 2 / 3) + 1;

const slideExcerpts = [];
for (let i = searchStart3; i <= totalSlides; i++) {
  const key = 'slide_' + i;
  const entry = outlineAlignment[key] || {};
  if (entry.has_outline_evidence && entry.outline_excerpt) {
    slideExcerpts.push('Slide ' + i + ' (' + (entry.outline_section || '') + '): ' + entry.outline_excerpt);
  }
}

const preWorkMeta = validatedInput.pre_work_metadata || {};
const competencies = Array.isArray(preWorkMeta.competencies) ? preWorkMeta.competencies : [];
const themes = Array.isArray(preWorkMeta.development_themes) ? preWorkMeta.development_themes : [];
const fallbackTerms = [...competencies, ...themes].filter(Boolean).join(', ');

const systemPrompt = 'You are a knowledge base search assistant at Jombay. '
  + 'Search for frameworks, models, and reusable content units relevant to the specified slides. '
  + 'Call search_knowledge_base with targeted queries based on the slide content provided.\n\n'
  + 'RULES:\n'
  + '- Find exactly 5 content units most relevant to slides ' + searchStart3 + '-' + totalSlides + '\n'
  + '- These slides cover engagement, activities, reflection, and closing — search for activities, exercises, and action-oriented content\n'
  + '- Return results as a JSON array of content units\n'
  + '- Include: content_unit_id, title, content_summary, content_type, document_url (MUST be the Google Drive URL of the source document, not S3)\n'
  + '- Do NOT fabricate results — only return what the search tool returns\n'
  + '- For document_url: always use the Google Drive or Google Docs URL (drive.google.com or docs.google.com)';

const userPrompt = 'Search the knowledge base for content relevant to slides ' + searchStart3 + '-' + totalSlides + ' of this training session.\n\n'
  + '=== SESSION CONTEXT ===\n'
  + 'Client: ' + (validatedInput.client_name || '') + '\n'
  + 'Industry: ' + (projectDetails.industry || 'Not specified') + '\n'
  + 'Audience level: ' + (projectDetails.seniority_of_cohort || 'Not specified') + '\n'
  + 'Program: ' + (projectDetails.name || 'Not specified') + '\n'
  + 'Session type: ' + (sessionConstraints.sessionType || sessionConstraints.session_type || 'Not specified') + '\n\n'
  + '=== SLIDE CONTENT TO MATCH (slides ' + searchStart3 + '-' + totalSlides + ') ===\n'
  + (slideExcerpts.length > 0
    ? slideExcerpts.join('\n\n')
    : 'No outline excerpts available. Search using: ' + (fallbackTerms || 'program name and content type'))
  + '\n\n'
  + '=== INSTRUCTIONS ===\n'
  + '1. Call search_knowledge_base with queries derived from the slide content above\n'
  + '2. Focus on activities, exercises, discussion prompts, and action planning content\n'
  + '3. Return exactly 5 results as a JSON array with content_unit_id, title, content_summary, content_type, document_url\n'
  + '4. For document_url, always return the Google Drive URL (drive.google.com or docs.google.com) — never return S3 URLs';

return [{ json: {
  system_prompt: systemPrompt,
  prompt: userPrompt,
  model: 'global.anthropic.claude-haiku-4-5-20251001-v1:0',
  node_name: 'KBSearch_Slides' + searchStart3 + 'to' + totalSlides,
  memory_id: validatedInput.memory_id,
  knowledge_base_id: validatedInput.knowledge_base_id,
  workflow_session_id: validatedInput.workflow_session_id,
  workflow_id: validatedInput.workflow_id,
  project_id: validatedInput.project_id,
  client_id: validatedInput.client_id
}}];

// 2.7b_JS_MergeKB — Merge 3 parallel KB search results
// Input: 3 items from 2.7a_MRG_KB (wait node)
// Output: Deduplicated KB results array, capped at 15

const items = $input.all();
let allResults = [];

for (const item of items) {
  const data = item.json;
  const llmResponse = data.llm_response || data;

  let results = [];
  if (Array.isArray(llmResponse)) {
    results = llmResponse;
  } else if (typeof llmResponse === 'object' && llmResponse !== null) {
    results = llmResponse.search_results
      || llmResponse.knowledge_base_results
      || llmResponse.results
      || llmResponse.content_units
      || llmResponse.kb_results
      || [];
    if (results.length === 0 && llmResponse.data) {
      results = Array.isArray(llmResponse.data) ? llmResponse.data : [llmResponse.data];
    }
  }

  if (!Array.isArray(results)) results = [results];
  allResults.push(...results);
}

// Deduplicate by content_unit_id
const seen = {};
const deduped = [];
for (const r of allResults) {
  if (!r || typeof r !== 'object') continue;
  const id = r.content_unit_id || r.id || '';
  if (!id || seen[id]) continue;
  seen[id] = true;

  // Strip s3_location and redundant URL fields, resolve document_url
  const { s3_location, result_index, source_url, drive_url, url, ...rest } = r;

  // Collect all candidate URLs
  const candidates = [
    rest.document_url,
    source_url,
    drive_url,
    url,
    s3_location
  ].filter(Boolean);

  // Prefer Drive URLs over everything else
  const isDriveUrl = (u) =>
    typeof u === 'string' && (u.includes('drive.google.com') || u.includes('docs.google.com'));

  rest.document_url = candidates.find(isDriveUrl) || candidates[0] || '';

  if (!rest.content_type) {
    const title = (rest.title || '').toLowerCase();
    if (title.includes('framework') || title.includes('model')) rest.content_type = 'framework';
    else if (title.includes('case study') || title.includes('scenario')) rest.content_type = 'case_study';
    else if (title.includes('exercise') || title.includes('activity')) rest.content_type = 'activity';
    else if (title.includes('video') || title.includes('watch')) rest.content_type = 'video';
    else if (title.includes('assessment') || title.includes('tool')) rest.content_type = 'tool';
    else rest.content_type = 'reference';
  }
  deduped.push(rest);
}

const kbResults = deduped.slice(0, 15);

return [{ json: {
  status: 'kb_merged',
  kb_results: kbResults,
  kb_result_count: kbResults.length,
  sources_merged: items.length
}}];

// 8.2a_FMT_GammaScript — Format prompt for full-content Gamma markdown
// Input: final_output from 8.1_JS_Assemble (tab-structured slides)
// Output: Haiku prompt to generate 15-25K chars of complete presentation markdown

const assembled = $input.first().json;
const output = assembled.final_output || {};
const validatedInput = $('1.2_PREP_Input').first().json;

const meta = output.metadata || {};
const overview = output.session_overview || {};
const slides = output.slides || {};

// Dynamic slide count from metadata
const totalSlides = meta.total_slides || Object.keys(slides).length || 17;

// Layout mapping (slide_type → Gamma layout tag)
const layoutMap = {
  'Session title': 'Title',
  'Jombay intro': 'Image + Text',
  'Trainer intro': 'Image + Text',
  'Agenda': 'Timeline',
  'Working Agreement': 'List',
  'Program overview': 'Timeline',
  'Objectives': 'List',
  'Module breaker': 'Title',
  'Content (AC)': 'Two Column',
  'Quote': 'Quote',
  'Discussion/Reflection (RO)': 'Image + Text',
  'Activity (CE)': 'List',
  'Break': 'Title',
  'Questions': 'CTA',
  'Feedback': 'List',
  'Call to Action (AE)': 'Two Column',
  'Closing': 'CTA'
};

// Build slide data from correct tab-structured keys
const slideData = [];
for (let i = 1; i <= totalSlides; i++) {
  const key = 'slide_' + i;
  const slide = slides[key] || {};
  const slideContent = slide.content || {};
  const facilitatorData = slide.facilitator || {};
  const gammaDetails = slide.gamma_details || {};
  const slideType = slideContent.slide_type || 'Content';
  const layout = layoutMap[slideType] || 'List';

  slideData.push({
    slide_number: i,
    slide_type: slideType,
    layout: layout,
    title: slideContent.slide_title || slideContent.headline || slideContent.title || 'Untitled',
    headline: slideContent.headline || '',
    subtext: slideContent.subtext || '',
    bullets: slideContent.bullets || [],
    visual_guidance: gammaDetails.visual_guidance || gammaDetails.visual_direction || '',
    activity: slideContent.activity || {},
    facilitation_tips: facilitatorData.facilitation_tips || slideContent.facilitation_tips || [],
    modality_notes: facilitatorData.modality_notes || slideContent.modality_notes || {},
    provenance: slideContent.provenance || 'New',
    provenance_source: slideContent.provenance_source || '',
    facilitator_script: facilitatorData.facilitator_script || facilitatorData.talking_points || ''
  });
}

// Build human-readable slide text — NOT JSON.stringify
// (stringify confuses LLM into returning JSON instead of markdown)
const slideDataText = slideData.map(s => {
  const bullets = Array.isArray(s.bullets)
    ? s.bullets
        .map(b => typeof b === 'string' ? b : (b.text || b.flag || JSON.stringify(b)))
        .filter(Boolean)
    : [];

  const lines = [
    'Slide ' + s.slide_number + ': ' + s.title,
    'Type: ' + s.slide_type + ' | Layout: ' + s.layout +
      ' | Provenance: ' + s.provenance +
      (s.provenance_source ? ' (' + s.provenance_source + ')' : '')
  ];
  if (s.headline && s.headline !== s.title) lines.push('Headline: ' + s.headline);
  if (s.subtext) lines.push('Subtext: ' + s.subtext);
  if (bullets.length) lines.push('Bullets:\n  - ' + bullets.join('\n  - '));
  if (s.visual_guidance) lines.push('Visual: ' + s.visual_guidance);
  if (s.activity && Object.keys(s.activity).length) {
    lines.push('Activity: ' + (typeof s.activity === 'string' ? s.activity : JSON.stringify(s.activity)));
  }
  if (Array.isArray(s.facilitation_tips) && s.facilitation_tips.length) {
    lines.push('Tips: ' + s.facilitation_tips.join('; '));
  }
  const mn = s.modality_notes;
  if (mn && (mn.virtual || mn.in_person)) {
    lines.push('Modality — Virtual: ' + (mn.virtual || '') + ' | In-person: ' + (mn.in_person || ''));
  }
  if (s.facilitator_script) lines.push('Facilitator Script: ' + s.facilitator_script);
  return lines.join('\n');
}).join('\n\n---\n\n');

